/* Small Business OS — dependency-free interactive demo frontend. */
const S = { me:null, business:null, page:'dashboard', conversations:[], contacts:[], appointments:[], services:[], staff:[], convId:null, inboxFilter:'all', weekAnchor:null };
const I = {
  grid:'<rect x="3" y="3" width="7" height="7" rx="1.4"/><rect x="14" y="3" width="7" height="7" rx="1.4"/><rect x="3" y="14" width="7" height="7" rx="1.4"/><rect x="14" y="14" width="7" height="7" rx="1.4"/>',
  chat:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8A8.5 8.5 0 0 1 12.5 20a8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8A8.5 8.5 0 0 1 12.5 3H13a8.5 8.5 0 0 1 8 8v.5Z"/>',
  users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',
  bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7l0-8Z"/>',
  spark:'<path d="m12 3 1.6 6 6 1.5-6 1.5-1.6 6-1.6-6L4.4 10.5l6-1.5L12 3ZM19 17l.6 2.4L22 20l-2.4.6L19 23l-.6-2.4L16 20l2.4-.6L19 17Z"/>',
  settings:'<path d="M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7Z"/><path d="m19.4 15 .2.2 1.4 1.1-1.4 2.5-1.7-.6a8.7 8.7 0 0 1-1.9 1.1l-.3 1.8h-3l-.3-1.8a8.7 8.7 0 0 1-1.9-1.1l-1.7.6-1.4-2.5 1.4-1.1a8 8 0 0 1 0-2.3l-1.4-1.1 1.4-2.5 1.7.6a8.7 8.7 0 0 1 1.9-1.1l.3-1.8h3l.3 1.8a8.7 8.7 0 0 1 1.9 1.1l1.7-.6 1.4 2.5-1.4 1.1a8 8 0 0 1 0 2.3"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
  send:'<path d="m22 2-7 20-4-9-9-4 20-7ZM22 2 11 13"/>',
  phone:'<path d="M22 16.9v3a2 2 0 0 1-2.2 2A19.7 19.7 0 0 1 3.1 5.2 2 2 0 0 1 5.1 3h3a2 2 0 0 1 2 1.7l.5 3a2 2 0 0 1-.6 1.7L8 11a15.7 15.7 0 0 0 5 5l1.6-2a2 2 0 0 1 1.7-.6l3 .5a2 2 0 0 1 1.7 2Z"/>',
  mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 7 10 7 10-7"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
  logout:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4m7 14 5-5-5-5m5 5H9"/>',
  chevron:'<path d="m9 18 6-6-6-6"/>',
  chevronLeft:'<path d="m15 18-6-6 6-6"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  alert:'<circle cx="12" cy="12" r="10"/><path d="M12 7v6M12 17h.01"/>',
  close:'<path d="M18 6 6 18M6 6l12 12"/>',
  more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
  book:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',
  copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',
  trend:'<path d="m3 16 6-6 4 4 8-8M15 6h6v6"/>',
  shield:'<path d="m12 22 7-4V6l-7-4-7 4v12l7 4Z"/><path d="m9 12 2 2 4-4"/>',
  globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3 3 15 0 18M12 3c-3 3-3 15 0 18"/>',
  refresh:'<path d="M20 11a8 8 0 0 0-14-5L3 9m0-5v5h5M4 13a8 8 0 0 0 14 5l3-3m0 5v-5h-5"/>',
};
const svg=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${I[name]||I.grid}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const money=n=>'$'+Number(n||0).toFixed(Number(n)%1?2:0);
const initials=name=>(String(name||'?').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase());
const avatar=(name,idx=0,sz='sm')=>`<div class="avatar ${sz} ${['','coral','mint','blue'][idx%4]}">${esc(initials(name))}</div>`;
const badge=(label,color='purple')=>`<span class="tag ${color}">${esc(label)}</span>`;
const ago=(v)=>{if(!v)return '—';let delta=Math.max(0,Math.floor((Date.now()-new Date(v).getTime())/60000));return delta<1?'Just now':delta<60?`${delta}m ago`:delta<1440?`${Math.floor(delta/60)}h ago`:new Date(v).toLocaleDateString('en-US',{month:'short',day:'numeric'});};
const tzDate=(v,zone=S.business?.timezone||'America/Chicago')=>new Intl.DateTimeFormat('en-US',{timeZone:zone,month:'short',day:'numeric'}).format(new Date(v));
const tzTime=(v,zone=S.business?.timezone||'America/Chicago')=>new Intl.DateTimeFormat('en-US',{timeZone:zone,hour:'numeric',minute:'2-digit',hour12:true}).format(new Date(v));
const localDate=(v=new Date(),zone=S.business?.timezone||'America/Chicago')=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(v)).filter(p=>p.type!=='literal').map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`;};
const addDate=(s,n)=>{let d=new Date(`${s}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const monday=s=>{const n=new Date(`${s}T12:00:00Z`).getUTCDay();return addDate(s,-((n+6)%7))};
const dlabel=s=>new Date(`${s}T12:00:00Z`).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
const field=(name,label,value='',type='text',placeholder='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${type==='number'?'min="0"':''} /></div>`;
const options=(items,selected)=>items.map(x=>`<option value="${x.id}" ${String(selected)===String(x.id)?'selected':''}>${esc(x.name)}</option>`).join('');
const E=id=>document.getElementById(id);
async function api(path,method='GET',body){const opt={method,credentials:'same-origin',headers:{}};if(body!==undefined){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(body)}let res=await fetch('/api'+path,opt),data;try{data=await res.json()}catch{data={detail:'Unexpected server response'}}if(!res.ok)throw new Error(typeof data.detail==='string'?data.detail:`Request failed (${res.status})`);return data;}
function toast(message,isError=false){const host=E('toast-root');const div=document.createElement('div');div.className='toast'+(isError?' error':'');div.textContent=message;const stack=host.querySelector('.toast-stack')||document.createElement('div');stack.className='toast-stack';if(!stack.parentNode)host.appendChild(stack);stack.appendChild(div);setTimeout(()=>div.remove(),3800)}
async function safe(job){try{await job()}catch(err){console.error(err);toast(err.message||'Something went wrong',true)}}
function modal(title,body,footer='',wide=false){E('modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><div class="modal-head"><h3>${title}</h3><button class="modal-close" onclick="closeModal()" aria-label="Close">${svg('close',15)}</button></div><div class="modal-content">${body}</div><div class="modal-footer">${footer||`<button class="btn outline" onclick="closeModal()">Close</button>`}</div></div></div>`}
function closeModal(){E('modal-root').innerHTML=''}
function formData(id){return Object.fromEntries(new FormData(E(id)).entries())}
function header(title,sub='',actions=''){return `<div class="page-head"><div><p class="eyebrow">WORKSPACE / ${esc(title.toUpperCase())}</p><h1 class="page-title">${esc(title)}</h1><p class="page-sub">${sub}</p></div><div class="actions">${actions}</div></div>`}
const NAV=[['dashboard','Overview','grid'],['inbox','Inbox','chat'],['contacts','Contacts','users'],['calendar','Calendar','calendar'],['automations','Automations','bolt'],['ai','AI Integration','spark'],['settings','Settings','settings']];
function appShell(){E('app').innerHTML=`<div class="app-layout"><aside class="sidebar"><div class="brand"><div class="brand-glyph">✳</div><div><div class="brand-title">smallbiz<span style="color:#afa9ff">.os</span></div><div class="brand-sub">BUSINESS MADE SIMPLE</div></div></div><div class="sidebar-group">WORKSPACE</div><nav id="nav-list">${NAV.slice(0,5).map(navItem).join('')}</nav><div class="sidebar-group">MANAGE</div><nav id="nav-settings">${NAV.slice(5).map(navItem).join('')}</nav><div class="sidebar-spacer"></div><div class="sidebar-card"><div class="spark">✦</div><strong>Try the full customer journey</strong><p>Simulate a missed call, receive a message and convert it into a booking.</p><button onclick="openDemoFlow()">Launch demo flow →</button></div><div class="user-box">${avatar(S.me.user.name,1,'sm')}<div class="user-meta"><strong>${esc(S.me.user.name)}</strong><span>${esc(S.me.role)} account</span></div><button class="signout" title="Sign out" onclick="signOut()">${svg('logout',17)}</button></div></aside><main class="main"><header class="topbar"><div class="bread">Workspace <span class="slash">/</span> <strong id="crumb">Overview</strong></div><div class="top-actions"><span class="demo-pill">● LOCAL DEMO</span><select id="workspace-picker" class="workspace-select" aria-label="Select business" onchange="switchBusiness(this.value)">${S.me.businesses.map(b=>`<option value="${b.id}" ${b.id===S.me.business_id?'selected':''}>${esc(b.name)}</option>`).join('')}</select><span class="top-divider"></span><button class="circle-ico" onclick="navigate('settings')" title="Settings">${svg('settings',20)}</button>${avatar(S.me.user.name,1,'sm')}</div></header><div id="content" class="content"></div></main></div>`}
function navItem(item){return `<button class="nav-item ${S.page===item[0]?'active':''}" data-page="${item[0]}" onclick="navigate('${item[0]}')">${svg(item[2])}<span>${item[1]}</span></button>`}
async function boot(){try{S.me=await api('/auth/me');S.business=await api('/business');S.weekAnchor=localDate();appShell();navigate('dashboard')}catch{showLogin()}}
function showLogin(){E('app').innerHTML=`<div class="login-page"><section class="login-art"><div class="art-brand"><i>✳</i> smallbiz.os</div><h1>Less admin.<br>More <span>business.</span></h1><p>A simpler home for your customers, conversations, appointments and automations. Built for small teams.</p><div class="art-bottom">INTERACTIVE PRODUCT DEMO · NO PAYMENTS · SMS MOCK BY DEFAULT</div></section><section class="login-form-area"><div class="login-panel"><p class="eyebrow">WELCOME BACK</p><h2>Sign in to your workspace</h2><p class="desc">Explore a fully functional demo with sample business data.</p><form id="login-form"><div class="field"><label>Email address</label><input type="email" name="email" required value="demo@smallbiz.local"></div><div class="field"><label>Password</label><input type="password" name="password" required value="demo123"></div><button type="submit" class="btn primary w100">Sign in to dashboard ${svg('arrow')}</button></form><div class="demo-credentials"><h4>✦ Demo access included</h4><p>Multi-business demo: <code>demo@smallbiz.local</code><br>Owner-only Luna: <code>luna@demo.local</code><br>Owner-only BrightHome: <code>bright@demo.local</code><br>Staff (restricted): <code>staff@luna.demo</code><br>All passwords: <code>demo123</code></p></div></div></section></div>`;E('login-form').addEventListener('submit',e=>{e.preventDefault();safe(async()=>{const f=formData('login-form');await api('/auth/login','POST',f);await boot()})})}
async function signOut(){await safe(async()=>{await api('/auth/logout','POST');S.me=null;showLogin();toast('Signed out')})}
async function switchBusiness(id){await safe(async()=>{await api('/auth/switch','POST',{business_id:Number(id)});S.me=await api('/auth/me');S.business=await api('/business');S.convId=null;S.contacts=[];S.conversations=[];S.weekAnchor=localDate();appShell();await navigate('dashboard');toast('Workspace switched')})}
async function navigate(page){S.page=page;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===page));if(E('crumb'))E('crumb').textContent=NAV.find(x=>x[0]===page)?.[1]||'Overview';E('content').innerHTML='<div class="empty">Loading data...</div>';await safe(async()=>{if(page==='dashboard')return renderDashboard();if(page==='inbox')return renderInbox();if(page==='contacts')return renderContacts();if(page==='calendar')return renderCalendar();if(page==='automations')return renderAutomations();if(page==='ai')return renderAI();if(page==='settings')return renderSettings()})}
async function reload(){await navigate(S.page)}
/* --- OVERVIEW --- */
async function renderDashboard(){const [d,b]=await Promise.all([api('/dashboard'),api('/business')]);S.business=b;const c=d.counts;const max=Math.max(1,...d.volume.map(v=>v.count));E('content').innerHTML=`${header('Good day, '+S.me.user.name.split(' ')[0]+' ✨',`Here’s what’s happening at ${esc(b.name)} today.`, `<button class="btn outline" onclick="openDemoFlow()">${svg('phone')} Simulate event</button><button class="btn primary" onclick="openAppointment()">${svg('plus')} New appointment</button>`)}<div class="hero"><div class="hero-copy"><div class="tiny">✦ SMALL BUSINESS, BIG POSSIBILITIES</div><h2>Every conversation is an opportunity.</h2><p>Your customers, messages and bookings are all in one place. Try a live mock customer journey to see it work.</p></div><div class="hero-icon">✳</div></div><div class="stats">${statCard('Total contacts',c.contacts,'users','Your customer database','')}${statCard('Open conversations',c.open_conversations,'chat','Ready for follow-up','green')}${statCard('Appointments',c.appointments,'calendar','Total scheduled','orange')}${statCard('New leads',c.leads,'trend','Potential new clients','blue')}</div><div class="grid-2"><div class="card"><div class="card-h"><div><div class="card-title">Customer messages</div><div class="card-sub">Inbound SMS · last 7 days · mock data</div></div>${badge('LIVE DATA','purple')}</div><div class="mini-chart">${d.volume.map(v=>`<div class="bar-wrap" style="--h:${Math.round(v.count/max*140)}px"><em>${v.count||''}</em><div class="bar" style="height:${Math.max(5,Math.round(v.count/max*140))}px"></div><span>${new Date(v.day+'T12:00:00Z').toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'})}</span></div>`).join('')}</div></div><div class="card"><div class="card-h"><div><div class="card-title">Recent activity</div><div class="card-sub">What’s happening across your workspace</div></div></div><div class="activity-list">${d.activity.length?d.activity.slice(0,5).map(a=>`<div class="activity-item"><div class="activity-icon">${svg(a.type==='booking'?'calendar':'chat',15)}</div><div style="min-width:0"><div class="line1">${esc(a.person)} <span class="muted">· ${a.type==='booking'?'New appointment':'Conversation'}</span></div><div class="line2">${esc(String(a.title).slice(0,62))} · ${ago(a.at)}</div></div></div>`).join(''):'<div class="empty">No activity yet</div>'}</div></div></div><div class="card section-spacer table-card"><div class="card-h"><div><div class="card-title">Upcoming appointments</div><div class="card-sub">Your next scheduled visits</div></div><button class="btn outline mini" onclick="navigate('calendar')">View calendar ${svg('arrow',13)}</button></div><table class="table"><thead><tr><th>Customer</th><th>Service</th><th>Date & time</th><th>Staff member</th><th>Status</th></tr></thead><tbody>${d.upcoming.length?d.upcoming.map((a,i)=>`<tr><td><div class="person">${avatar(a.contact,i)}${esc(a.contact)}</div></td><td>${esc(a.service)}</td><td>${tzDate(a.starts_at)} · ${tzTime(a.starts_at)}</td><td>${esc(a.staff)}</td><td>${badge('Confirmed','green')}</td></tr>`).join(''):'<tr><td colspan="5">No upcoming appointments</td></tr>'}</tbody></table></div>`}
function statCard(label,value,type,foot,color=''){return `<div class="stat card"><div class="stat-top"><span class="stat-label">${label}</span><div class="stat-ico ${color}">${svg(type,17)}</div></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
/* --- INBOX --- */
async function renderInbox(){S.conversations=await api('/conversations');if(!S.conversations.some(x=>x.id===S.convId))S.convId=S.conversations[0]?.id||null;const current=S.conversations.find(x=>x.id===S.convId);const msgs=current?await api(`/conversations/${current.id}/messages`):[];E('content').innerHTML=`${header('Unified inbox','All customer conversations in one beautiful place.',`<button class="btn outline" onclick="openDemoFlow()">${svg('phone')} Simulate event</button><button class="btn primary" onclick="openInbound()">${svg('plus')} New message</button>`)}<div class="card inbox-shell"><section class="inbox-list"><div class="inbox-list-head"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><strong style="font-size:14px">Conversations</strong>${badge(S.conversations.length,'purple')}</div><label class="searchbox">${svg('search')}<input id="inbox-query" placeholder="Search messages..." oninput="filterInbox()"></label><div class="chips"><button class="chip ${S.inboxFilter==='all'?'active':''}" onclick="setInboxFilter('all')">All</button><button class="chip ${S.inboxFilter==='open'?'active':''}" onclick="setInboxFilter('open')">Open</button><button class="chip ${S.inboxFilter==='external'?'active':''}" onclick="setInboxFilter('external')">External AI</button></div></div><div class="conv-scroll" id="conv-scroll">${inboxRows()}</div></section><section class="thread">${current?`<div class="thread-head"><div><div class="person-name">${esc(current.contact_name)}</div><div class="small">${svg('phone',11)} ${esc(current.contact_phone)} · ${esc(current.channel)}</div></div><div class="actions">${badge(current.status==='open'?'Open':'Closed',current.status==='open'?'green':'gray')}<button class="btn outline mini" onclick="toggleConvStatus(${current.id},'${current.status}')">${current.status==='open'?'Close':'Reopen'}</button></div></div><div class="thread-messages" id="thread-messages">${msgs.map(m=>`<div class="message-bubble ${m.direction}"><div class="message-body">${esc(m.body)}</div><div class="message-meta">${m.direction==='inbound'?'Customer':m.author==='external_ai'?'External AI':m.author==='automation'?'Automation (mock)':'Team (mock)'} · ${ago(m.created_at)}</div></div>`).join('')||'<div class="empty">No messages yet</div>'}</div><div class="compose"><form class="compose-form" id="reply-form"><textarea name="body" placeholder="Write a message..." required></textarea><div class="compose-foot"><span>◉ SMS delivery follows channel settings (Mock by default)</span><button class="btn primary mini" type="submit">Send ${svg('send',13)}</button></div></form></div>`:'<div class="empty" style="margin:auto">No conversations. Simulate an inbound SMS to begin.</div>'}</section>${current?`<aside class="contact-sidebar"><div class="contact-profile">${avatar(current.contact_name,1,'lg')}<h3>${esc(current.contact_name)}</h3><p>${esc(current.contact_phone)}</p>${badge('Customer','purple')}</div><div class="switch-row"><div><b>Reply mode</b><p>${current.ai_mode==='external'?'External agent':current.ai_mode==='builtin'?'Configured AI provider':'Handled by team'}</p></div><select class="mode-select" onchange="setReplyMode(${current.id},this.value)"><option value="human" ${current.ai_mode==='human'?'selected':''}>Human</option><option value="builtin" ${current.ai_mode==='builtin'?'selected':''}>Built-in AI</option><option value="external" ${current.ai_mode==='external'?'selected':''}>External AI</option></select></div><div class="contact-info"><div class="info-row"><span>Contact ID</span><strong>#${current.contact_id}</strong></div><div class="info-row"><span>Channel</span><strong>${esc(current.channel)}</strong></div><div class="info-row"><span>SMS consent</span>${badge(current.consent_sms?'Yes':'Not recorded',current.consent_sms?'green':'orange')}</div><div class="info-row"><span>Last activity</span><strong>${ago(current.last_message_at)}</strong></div></div><button class="btn outline w100" onclick="contactDetails(${current.contact_id})">${svg('users')} View contact</button><div class="info-note" style="margin-top:20px">${svg('spark',14)} Built-in AI requires a configured provider and auto-reply enabled. External AI uses the agent token API.</div></aside>`:''}</div>`;const thread=E('thread-messages');if(thread)thread.scrollTop=thread.scrollHeight;E('reply-form')?.addEventListener('submit',e=>{e.preventDefault();const f=formData('reply-form');safe(async()=>{await api(`/conversations/${S.convId}/messages`,'POST',{body:f.body});await renderInbox();toast('Message processed using SMS channel settings')})})}
function inboxRows(){const q=E('inbox-query')?.value?.toLowerCase()||'';return S.conversations.filter(x=>(S.inboxFilter==='all'||x.status===S.inboxFilter||x.ai_mode===S.inboxFilter)&&(!q||x.contact_name.toLowerCase().includes(q)||String(x.last_message||'').toLowerCase().includes(q))).map((co,i)=>`<div class="conv-row ${co.id===S.convId?'selected':''}" onclick="selectConversation(${co.id})">${avatar(co.contact_name,i)}<div class="conv-text"><div class="conv-line"><strong>${esc(co.contact_name)}</strong><time>${ago(co.last_message_at)}</time></div><div class="conv-preview">${esc(co.last_message||'No messages')}</div><div class="conv-pills">${badge(co.channel,'blue')}${co.ai_mode==='external'?badge('External AI','purple'):''}${co.status==='closed'?badge('Closed','gray'):''}</div></div></div>`).join('')||'<div class="empty">Nothing matches this filter.</div>'}
function filterInbox(){E('conv-scroll').innerHTML=inboxRows()}
function setInboxFilter(filter){S.inboxFilter=filter;renderInbox()}
function selectConversation(id){S.convId=id;renderInbox()}
async function toggleAIMode(id,mode){await safe(async()=>{await api(`/conversations/${id}`,'PATCH',{ai_mode:mode==='external'?'human':'external'});await renderInbox();toast(mode==='external'?'Handed to staff':'Conversation queued for external AI')})}
async function toggleConvStatus(id,status){await safe(async()=>{await api(`/conversations/${id}`,'PATCH',{status:status==='open'?'closed':'open'});await renderInbox()})}
async function openInbound(){const contacts=await api('/contacts');if(!contacts.length){toast('Create a contact first',true);return}modal('Simulate inbound SMS',`<div class="notice">This creates a realistic inbound conversation in the mock inbox. No SMS is actually transmitted.</div><form id="inbound-form"><div class="field"><label>Customer</label><select name="contact_id">${options(contacts)}</select></div><div class="field"><label>Inbound message</label><textarea name="text" required placeholder="Hi! Do you have a slot available tomorrow?">Hi! Can I book an appointment this week?</textarea></div></form>`,`<button class="btn outline" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="submitInbound()">${svg('chat')} Receive mock SMS</button>`)}
async function submitInbound(){await safe(async()=>{const f=formData('inbound-form');const r=await api('/demo/inbound-sms','POST',{contact_id:Number(f.contact_id),text:f.text});closeModal();S.convId=r.conversation_id;await navigate('inbox');toast('Mock SMS received')})}
async function openDemoFlow(){const contacts=await api('/contacts');if(!contacts.length){toast('Create a contact first',true);return}modal('Run a customer journey',`<div class="notice">Choose an existing contact and trigger a simulated missed call. If SMS consent is recorded and the rule is active, a mock text-back is created. You can then simulate a reply and add a booking.</div><form id="flow-form"><div class="field"><label>Customer</label><select name="contact_id">${options(contacts)}</select></div><div class="field"><label>Demo scenario</label><select name="kind"><option value="missed">Missed call → automatic mock text-back</option><option value="inbound">Incoming SMS → inbox conversation</option></select></div></form>`,`<button class="btn outline" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="runDemoFlow()">${svg('bolt')} Trigger event</button>`)}
async function runDemoFlow(){await safe(async()=>{const d=formData('flow-form');const payload={contact_id:Number(d.contact_id),event_key:crypto.randomUUID()};const r=d.kind==='missed'?await api('/demo/missed-call','POST',payload):await api('/demo/inbound-sms','POST',{...payload,text:'Hello! I would like to book an appointment.'});closeModal();S.convId=r.conversation_id;await navigate('inbox');toast(d.kind==='missed'?(r.mock_textback_sent?'Missed call logged + mock SMS text-back':'Call logged; SMS skipped because consent is missing or rule disabled'):'Inbound SMS received')})}
/* --- CRM CONTACTS --- */
async function renderContacts(){S.contacts=await api('/contacts');E('content').innerHTML=`${header('Contacts','Every customer relationship, all in one place.',`<button class="btn primary" onclick="openContact()">${svg('plus')} Add contact</button>`)}<div class="card table-card"><div class="toolbar"><label class="searchbox">${svg('search')}<input id="contact-search" placeholder="Search names, phones or email" oninput="filterContacts()"></label>${badge(`${S.contacts.length} contacts`,'purple')}</div><div id="contacts-table">${contactsTable(S.contacts)}</div></div>`}
function contactsTable(data){return `<table class="table"><thead><tr><th>Customer</th><th>Status</th><th>Source</th><th>Tags</th><th>Bookings</th><th>SMS consent</th><th></th></tr></thead><tbody>${data.map((ct,i)=>`<tr><td><div class="person">${avatar(ct.name,i)}<div><div class="td-main">${esc(ct.name)}</div><div class="td-small">${esc(ct.email||ct.phone)}</div></div></div></td><td>${badge(ct.status,ct.status==='Customer'?'green':'orange')}</td><td>${esc(ct.source)}</td><td>${ct.tags?ct.tags.split(',').slice(0,2).map(t=>badge(t.trim(),'gray')).join(' '):'—'}</td><td>${ct.bookings}</td><td>${badge(ct.consent_sms?'Yes':'No',ct.consent_sms?'green':'gray')}</td><td><button class="row-actions" onclick="contactDetails(${ct.id})">View ${svg('chevron',12)}</button></td></tr>`).join('')||'<tr><td colspan="7">No contacts found</td></tr>'}</tbody></table><div class="pagination">Showing ${data.length} of ${S.contacts.length} contacts</div>`}
function filterContacts(){const q=E('contact-search').value.toLowerCase();E('contacts-table').innerHTML=contactsTable(S.contacts.filter(ct=>[ct.name,ct.email,ct.phone,ct.tags].some(v=>String(v).toLowerCase().includes(q))))}
function openContact(ct=null){const edit=!!ct;modal(edit?'Edit contact':'Add a new contact',`<form id="contact-form"><div class="form-grid">${field('name','Full name',ct?.name||'','text','e.g. Taylor Smith')}${field('phone','Phone number',ct?.phone||'','tel','+1 512 555 0100')}</div><div class="field"><label>Email address</label><input type="email" name="email" value="${esc(ct?.email||'')}" placeholder="customer@example.com"></div><div class="form-grid"><div class="field"><label>Status</label><select name="status"><option ${ct?.status==='Lead'?'selected':''}>Lead</option><option ${ct?.status==='Customer'?'selected':''}>Customer</option></select></div><div class="field"><label>Source</label><select name="source">${['Manual','Google','Instagram','Referral','Phone','Walk-in','Website'].map(s=>`<option ${ct?.source===s?'selected':''}>${s}</option>`).join('')}</select></div></div>${field('tags','Tags (comma separated)',ct?.tags||'','text','VIP, New lead')}<label class="checkbox-row"><input type="checkbox" name="consent_sms" ${ct?.consent_sms?'checked':''}> Customer has explicitly opted in to receive SMS</label></form>`,`<button class="btn outline" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveContact(${ct?.id||'null'})">${svg('check')} ${edit?'Save changes':'Create contact'}</button>`)}
async function saveContact(id){await safe(async()=>{const f=formData('contact-form');const data={...f,consent_sms:E('contact-form').elements.consent_sms.checked};if(!data.name.trim()||!data.phone.trim()){toast('Name and phone number are required',true);return}await api(id?`/contacts/${id}`:'/contacts',id?'PATCH':'POST',data);closeModal();await reload();toast(id?'Contact updated':'New contact created')})}
async function contactDetails(id){await safe(async()=>{const ct=S.contacts.find(c=>c.id===id)|| (await api('/contacts')).find(c=>c.id===id);if(!ct)return toast('Contact not found',true);const tl=await api(`/contacts/${id}/timeline`);modal(`${esc(ct.name)} · Contact profile`,`<div style="display:flex;gap:14px;align-items:center;margin-bottom:20px">${avatar(ct.name,1,'lg')}<div><strong style="font-size:15px">${esc(ct.name)}</strong><p style="font-size:11px;color:#969eb1;margin:5px 0">${esc(ct.phone)} · ${esc(ct.email||'No email')}</p>${badge(ct.status,ct.status==='Lead'?'orange':'green')} ${badge(ct.consent_sms?'SMS consent recorded':'SMS not permitted',ct.consent_sms?'green':'gray')}</div></div><div style="display:flex;justify-content:space-between;align-items:center;margin:22px 0 12px"><strong style="font-size:13px">Notes</strong><span class="muted" style="font-size:11px">${tl.notes.length} notes</span></div><form id="note-form" style="display:flex;gap:8px"><input class="text-input" placeholder="Add a note about this customer" name="text" required><button type="submit" class="btn primary mini">Add</button></form><div style="margin-top:12px">${tl.notes.map(n=>`<div class="faq-row" style="padding-left:0;padding-right:0"><div class="answer">${esc(n.text)}</div><span class="muted" style="font-size:10px">${ago(n.created_at)}</span></div>`).join('')||'<p class="muted" style="font-size:12px">No notes yet</p>'}</div><div style="margin-top:22px"><strong style="font-size:13px">Recent messages</strong>${tl.messages.slice(0,6).map(m=>`<div class="list-entity"><div><strong>${esc(m.body)}</strong><p>${m.author} · ${ago(m.created_at)}</p></div></div>`).join('')||'<div class="empty">No messages yet</div>'}</div>`,`<button class="btn outline" onclick="closeModal()">Close</button><button class="btn primary" onclick="editContact(${id})">${svg('settings')} Edit contact</button>`,true);E('note-form').addEventListener('submit',e=>{e.preventDefault();safe(async()=>{const f=formData('note-form');await api(`/contacts/${id}/notes`,'POST',{text:f.text});toast('Note saved');await contactDetails(id)})})})}
async function editContact(id){const all=await api('/contacts');const ct=all.find(c=>c.id===id);if(ct)openContact(ct)}
/* --- CALENDAR + BOOKING --- */
async function renderCalendar(){const [appts,services,staff,contacts]=await Promise.all([api('/appointments'),api('/services'),api('/staff'),api('/contacts')]);Object.assign(S,{appointments:appts,services,staff,contacts});if(!S.weekAnchor)S.weekAnchor=localDate();const start=monday(S.weekAnchor),days=Array.from({length:7},(_,i)=>addDate(start,i));const today=localDate();E('content').innerHTML=`${header('Calendar','Keep every appointment, staff member and customer in sync.',`<button class="btn primary" onclick="openAppointment()">${svg('plus')} New appointment</button>`)}<div class="card"><div class="card-h"><div><div class="card-title">Team schedule</div><div class="card-sub">Timezone: ${esc(S.business?.timezone||'')} · ${S.appointments.filter(x=>x.status==='confirmed').length} active appointments</div></div><div class="calendar-toolbar"><button class="icon-btn" onclick="changeWeek(-7)" aria-label="Previous week">${svg('chevronLeft',16)}</button><span class="date-range">${dlabel(days[0])} – ${dlabel(days[6])}</span><button class="icon-btn" onclick="changeWeek(7)" aria-label="Next week">${svg('chevron',16)}</button><button class="btn outline mini" onclick="changeWeek(0)">Today</button></div></div><div class="divider"></div><div class="week-grid">${days.map(d=>`<div class="day-col"><div class="day-head ${d===today?'today':''}"><div class="weekday">${new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'})}</div><div class="daynumber">${Number(d.slice(-2))}</div></div>${S.appointments.filter(a=>localDate(a.starts_at)===d).map(a=>`<div class="appt-card ${a.status==='cancelled'?'cancelled':''}" style="border-color:${esc(a.service_color)};background:${esc(a.service_color)}17;cursor:pointer" onclick="appointmentDetails(${a.id})"><div class="time">${tzTime(a.starts_at)}</div><div class="name">${esc(a.contact_name)}</div><div class="detail">${esc(a.service_name)}</div><div class="detail">${esc(a.staff_name)}</div></div>`).join('')}</div>`).join('')}</div><div class="calendar-bottom">Tap an appointment to view details or change its status. Time slots are checked by the backend to prevent double booking.</div></div>`}
function changeWeek(n){S.weekAnchor=n===0?localDate():addDate(S.weekAnchor,n);renderCalendar()}
async function openAppointment(){await safe(async()=>{const [contacts,services,staff]=await Promise.all([api('/contacts'),api('/services'),api('/staff')]);Object.assign(S,{contacts,services,staff});if(!contacts.length||!services.length||!staff.length){toast('Add a contact, service and staff member first',true);return}modal('Create an appointment',`<form id="booking-form"><div class="field"><label>Customer</label><select name="contact_id">${options(contacts)}</select></div><div class="form-grid"><div class="field"><label>Service</label><select name="service_id" id="slot-service" onchange="loadSlots()">${options(services)}</select></div><div class="field"><label>Staff member</label><select name="staff_id" id="slot-staff" onchange="loadSlots()">${options(staff)}</select></div></div><div class="form-grid"><div class="field"><label>Date</label><input type="date" name="date" id="slot-date" min="${localDate()}" value="${localDate()}" onchange="loadSlots()"></div><div class="field"><label>Available start time</label><select name="starts_at" id="slot-time"><option>Loading...</option></select></div></div><div class="field"><label>Notes (optional)</label><textarea name="notes" placeholder="Customer requests or additional details"></textarea></div><div class="info-note">Available slots follow the business timezone (${esc(S.business?.timezone)}). Confirmed appointments are checked transactionally before creation.</div></form>`,`<button class="btn outline" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="submitAppointment()">${svg('calendar')} Confirm booking</button>`);loadSlots()})}
async function loadSlots(){await safe(async()=>{const f=formData('booking-form'),select=E('slot-time');if(!f.date)return;select.innerHTML='<option>Loading...</option>';const result=await api(`/availability?date=${encodeURIComponent(f.date)}&staff_id=${Number(f.staff_id)}&service_id=${Number(f.service_id)}`);select.innerHTML=result.slots.length?result.slots.map(s=>`<option value="${esc(s.starts_at)}">${esc(s.label)}</option>`).join(''):'<option value="">No available slots</option>'})}
async function submitAppointment(){await safe(async()=>{const f=formData('booking-form');if(!f.starts_at){toast('Select an available time slot',true);return}await api('/appointments','POST',{contact_id:Number(f.contact_id),service_id:Number(f.service_id),staff_id:Number(f.staff_id),starts_at:f.starts_at,notes:f.notes});closeModal();await reload();toast('Appointment booked successfully')})}
async function appointmentDetails(id){const a=S.appointments.find(x=>x.id===id);if(!a)return;modal('Appointment details',`<div style="display:flex;align-items:center;gap:12px;margin-bottom:22px">${avatar(a.contact_name,0,'lg')}<div><strong>${esc(a.contact_name)}</strong><div style="margin-top:5px">${badge(a.status,a.status==='confirmed'?'green':'gray')}</div></div></div><div class="info-row"><span>Service</span><strong>${esc(a.service_name)}</strong></div><div class="info-row"><span>Team member</span><strong>${esc(a.staff_name)}</strong></div><div class="info-row"><span>When</span><strong>${tzDate(a.starts_at)} · ${tzTime(a.starts_at)}</strong></div><div class="info-row"><span>Timezone</span><strong>${esc(S.business?.timezone)}</strong></div><div class="info-row"><span>Notes</span><strong>${esc(a.notes||'—')}</strong></div>`,`<button class="btn outline" onclick="closeModal()">Close</button>${a.status==='confirmed'?`<button class="btn danger" onclick="changeAppointmentStatus(${id},'cancelled')">Cancel appointment</button><button class="btn primary" onclick="changeAppointmentStatus(${id},'completed')">Mark completed</button>`:''}`)}
async function changeAppointmentStatus(id,status){await safe(async()=>{await api(`/appointments/${id}`,'PATCH',{status});closeModal();await reload();toast('Appointment updated')})}
/* --- AUTOMATIONS --- */
async function renderAutomations(){const data=await api('/automations');const iconByKey={missed_call:'phone',booking_confirm:'calendar',new_lead:'users'};E('content').innerHTML=`${header('Automations','Simple, useful automations without the complexity.',`<button class="btn outline" onclick="openDemoFlow()">${svg('bolt')} Test automation</button>`)}<div class="rule-grid">${data.rules.map((r,i)=>`<div class="card rule-card"><div class="rule-top"><div class="rule-icon">${svg(iconByKey[r.key]||'bolt',21)}</div><button class="switch ${r.enabled?'on':''}" onclick="toggleRule(${r.id},${r.enabled})" aria-label="Toggle ${esc(r.name)}"></button></div><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p><div class="rule-footer">${badge(r.enabled?'Enabled':'Paused',r.enabled?'green':'gray')}<span class="muted" style="font-size:10px">PRESET ${i+1}</span></div></div>`).join('')}</div><div class="card section-spacer"><div class="card-h"><div><div class="card-title">Execution history</div><div class="card-sub">Every event and action, including skipped SMS messages</div></div>${badge(`${data.logs.length} events`,'purple')}</div>${data.logs.length?data.logs.map(x=>`<div class="log-row"><div class="log-icon" style="${x.result==='skipped'?'color:#dc9f45;background:#fff4df':''}">${svg(x.result==='skipped'?'alert':'check',17)}</div><div><strong>${esc(x.rule_key.replaceAll('_',' '))} · ${esc(x.result)}</strong><span>${esc(x.detail)}</span></div><time>${ago(x.created_at)}</time></div>`).join(''):'<div class="empty">No events yet. Run a mock scenario to see execution logs.</div>'}</div><div class="info-note" style="margin-top:18px">Automations run only in mock mode. SMS text-back is skipped when a contact has not recorded SMS consent. Duplicate webhook events can be de-duplicated via event keys.</div>`}
async function toggleRule(id,enabled){await safe(async()=>{await api(`/automations/${id}`,'PATCH',{enabled:!enabled});await renderAutomations();toast(enabled?'Automation paused':'Automation enabled')})}
/* --- AI CONNECTOR (NO MODEL / NO GENERATED RESPONSE) --- */
async function renderAI(){const info=await api('/ai');E('content').innerHTML=`${header('AI Integration','Bring your own AI agent. The reply engine is intentionally separate.',`<button class="btn outline" onclick="copyText('/api/integrations/ai/inbox')">${svg('copy')} Copy API route</button><button class="btn primary" onclick="addFAQ()">${svg('plus')} Add knowledge</button>`)}<div class="ai-banner"><div class="ai-orb">✳</div><div><h3>Your agent. Your intelligence.</h3><p>This demo includes a secure integration interface, CRM context and booking tools — but no built-in LLM or generated replies. Connect your own AI when ready.</p></div></div><div class="ai-layout"><div><div class="card pad-card"><div style="display:flex;justify-content:space-between;align-items:center"><div class="card-title">External AI connector</div>${badge('READY FOR INTEGRATION','green')}</div><div class="card-sub" style="margin-bottom:17px">Business-scoped Bearer token · mock outbound messages</div><div class="ai-step"><div class="step-num">1</div><div><strong>Enable External AI for a conversation</strong><p>In Inbox, select a conversation and toggle “External AI”. Incoming messages then enter the agent polling queue.</p></div></div><div class="ai-step"><div class="step-num">2</div><div><strong>Agent polls, reads context and replies</strong><p>Your agent calls the endpoints below with a business token, reads customer info and knowledge, then posts a reply.</p></div></div><div class="ai-step"><div class="step-num">3</div><div><strong>Book or hand off to your team</strong><p>Your agent can create a validated appointment, or transfer the conversation back to a human.</p></div></div><div class="api-label">AGENT ENDPOINTS</div><div class="code">GET  /api/integrations/ai/inbox\nGET  /api/integrations/ai/context/{conversation_id}\nGET  /api/integrations/ai/availability\nPOST /api/integrations/ai/reply\nPOST /api/integrations/ai/book\nPOST /api/integrations/ai/handoff</div>${info.token?`<div class="api-label">INTEGRATION TOKEN · OWNER ONLY</div><div class="token-row"><input class="text-input" id="ai-token" type="password" readonly value="${esc(info.token)}"><button class="btn outline" onclick="revealToken()">Show</button><button class="btn outline" onclick="copyToken()">${svg('copy',14)}</button></div><div style="display:flex;gap:10px;align-items:center;justify-content:space-between;margin-top:10px"><span class="muted" style="font-size:10px">Keep it private. Rotate if compromised.</span><button class="btn mini outline" onclick="rotateToken()">Rotate token</button></div>`:'<div class="info-note" style="margin-top:15px">Only the workspace owner can view or rotate the integration token.</div>'}</div><div class="card section-spacer"><div class="card-h"><div><div class="card-title">Knowledge base</div><div class="card-sub">Facts your external AI can retrieve via API</div></div>${badge(`${info.knowledge.length} entries`,'blue')}</div>${info.knowledge.map(x=>`<div class="faq-row"><div style="display:flex;justify-content:space-between;gap:10px"><div class="question">${esc(x.question)}</div>${S.me.role==='owner'?`<button class="row-actions" onclick="deleteFAQ(${x.id})" style="color:#d16d7b">Remove</button>`:''}</div><div class="answer">${esc(x.answer)}</div></div>`).join('')||'<div class="empty">No knowledge entries.</div>'}</div></div><div><div class="card pad-card"><div class="card-title">Integration status</div><div class="card-sub" style="margin-bottom:20px">Live state of the demo connector</div><div class="info-row"><span>AI provider</span>${badge('Not connected','orange')}</div><div class="info-row"><span>Reply engine</span><strong>External only</strong></div><div class="info-row"><span>Pending agent messages</span><strong>${info.pending}</strong></div><div class="info-row"><span>SMS delivery</span>${badge('Mock mode','purple')}</div><div class="divider" style="margin:18px 0"></div><div class="card-title" style="font-size:12px;margin-bottom:9px">Example: reply request</div><div class="code">POST /api/integrations/ai/reply\nAuthorization: Bearer YOUR_TOKEN\nContent-Type: application/json\n\n{\n  "conversation_id": 1,\n  "inbound_message_id": 10,\n  "reply": "I can help with that!"\n}</div><div class="info-note" style="margin-top:17px">The example IDs are illustrative. Use IDs returned from the pending inbox endpoint. The response is saved as <b>mock_sent</b>; no real SMS is delivered.</div></div><div class="card pad-card section-spacer"><div class="card-title">Security boundary</div><p style="font-size:11px;line-height:1.8;color:#929aaf">Each AI token is bound to one business. The backend checks resource ownership, conversation AI mode and booking availability. This demo does not transmit customer data to any AI provider.</p><div style="margin-top:17px">${badge('Multi-tenant scoped','green')} ${badge('No payment system','blue')}</div></div></div></div>`}
function revealToken(){const inp=E('ai-token');inp.type=inp.type==='password'?'text':'password'}
async function copyText(t){await safe(async()=>{await navigator.clipboard.writeText(t);toast('Copied to clipboard')})}
async function copyToken(){await copyText(E('ai-token').value)}
async function rotateToken(){if(!confirm('Rotate the token? Your existing AI integration will stop working until updated.'))return;await safe(async()=>{await api('/ai/rotate-token','POST');await renderAI();toast('Token rotated')})}
function addFAQ(){modal('Add to knowledge base',`<form id="faq-form"><div class="field"><label>Customer question</label><input name="question" required placeholder="e.g. What are your opening hours?"></div><div class="field"><label>Approved answer</label><textarea name="answer" required placeholder="Provide verified business information..."></textarea></div></form>`,`<button class="btn outline" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveFAQ()">Add entry</button>`)}
async function saveFAQ(){await safe(async()=>{await api('/ai/knowledge','POST',formData('faq-form'));closeModal();await renderAI();toast('Knowledge added')})}
async function deleteFAQ(id){await safe(async()=>{await api(`/ai/knowledge/${id}`,'DELETE');await renderAI();toast('Knowledge entry removed')})}
/* --- SETTINGS --- */
async function renderSettings(){const [business,staff,services,audit,members]=await Promise.all([api('/business'),api('/staff'),api('/services'),api('/audit'),api('/members')]);S.business=business;S.staff=staff;S.services=services;E('content').innerHTML=`${header('Business settings','Your workspace, your team and how you serve customers.',S.me.role==='owner'?`<button class="btn outline" onclick="openBusiness()">${svg('plus')} Create workspace</button>`:'') }<div class="setting-grid"><div><div class="card pad-card"><div class="card-title" style="margin-bottom:6px">Business information</div><div class="card-sub" style="margin-bottom:22px">The details customers and external AI can reference</div><form id="biz-form"><div class="form-grid">${field('name','Business name',business.name)}${field('phone','Business phone',business.phone)}</div><div class="field"><label>Business address</label><input name="address" value="${esc(business.address)}"></div><div class="field"><label>Operating hours</label><input name="hours" value="${esc(business.hours)}"></div><div class="form-grid"><div class="field"><label>Industry</label><input disabled value="${esc(business.industry)}"></div><div class="field"><label>Timezone</label><input disabled value="${esc(business.timezone)}"></div></div><button type="submit" class="btn primary">${svg('check')} Save business details</button></form></div><div class="card section-spacer"><div class="card-h"><div><div class="card-title">Services & pricing</div><div class="card-sub">Used when calculating booking duration</div></div>${S.me.role==='owner'?`<button class="btn outline mini" onclick="openService()">${svg('plus',13)} Add service</button>`:''}</div><div style="padding:0 22px 14px">${services.map(s=>`<div class="list-entity"><div class="rule-icon" style="width:35px;height:35px;background:${esc(s.color)}22;color:${esc(s.color)}">${svg('book',16)}</div><div><strong>${esc(s.name)}</strong><p>${s.duration} minutes</p></div><div class="right"><strong>${money(s.price)}</strong></div></div>`).join('')}</div></div></div><div><div class="card"><div class="card-h"><div><div class="card-title">Team members</div><div class="card-sub">Manage who takes appointments</div></div><div style="padding:0 22px 15px">${staff.map((m,i)=>`<div class="list-entity">${avatar(m.name,i)}<div><strong>${esc(m.name)}</strong><p>${esc(m.title)}</p></div>${badge('Active','green')}</div>`).join('')}${S.me.role==='owner'?`<button class="btn outline w100" style="margin:15px 0" onclick="openStaff()">${svg('plus')} Add team member</button>`:''}</div></div><div class="card section-spacer"><div class="card-h"><div><div class="card-title">Workspace access</div><div class="card-sub">Account roles & login permissions</div></div></div><div style="padding:0 22px 15px">${members.map((m,i)=>`<div class="list-entity">${avatar(m.name,i)}<div><strong>${esc(m.name)}</strong><p>${esc(m.email)}</p></div>${badge(m.role,m.role==='owner'?'purple':'gray')}</div>`).join('')}${S.me.role==='owner'?`<button class="btn outline w100" style="margin:15px 0" onclick="openMember()">${svg('plus')} Add login member</button>`:''}</div></div><div class="card section-spacer"><div class="card-h"><div><div class="card-title">Recent changes</div><div class="card-sub">Workspace audit trail</div></div><div style="padding:0 20px 15px">${audit.slice(0,7).map(x=>`<div class="list-entity"><div class="log-icon">${svg('check',15)}</div><div><strong>${esc(x.action)}</strong><p>${esc(x.detail)} · ${ago(x.created_at)}</p></div></div>`).join('')}</div></div><div class="info-note section-spacer">✦ This is a local demo workspace. Authentication, roles, database records and tenant checks are functional. Public deployment requires security hardening, monitoring, backups and real provider configuration.</div></div></div>`;E('biz-form').addEventListener('submit',e=>{e.preventDefault();safe(async()=>{await api('/business','PATCH',formData('biz-form'));S.business=await api('/business');toast('Business details updated')})})}
function openStaff(){modal('Add team member',`<form id="staff-form">${field('name','Staff name','','text','e.g. Jordan Lee')}${field('title','Job title','Team member')}</form>`,`<button class="btn outline" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveStaff()">Add member</button>`)}
async function saveStaff(){await safe(async()=>{await api('/staff','POST',formData('staff-form'));closeModal();await reload();toast('Team member added')})}
function openService(){modal('Add service',`<form id="service-form">${field('name','Service name','','text','e.g. Express manicure')}<div class="form-grid">${field('duration','Duration (minutes)','60','number')}${field('price','Price in USD','45','number')}</div></form>`,`<button class="btn outline" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveService()">Add service</button>`)}
async function saveService(){await safe(async()=>{const d=formData('service-form');await api('/services','POST',{name:d.name,duration:Number(d.duration),price:Number(d.price)});closeModal();await reload();toast('Service added')})}
function openBusiness(){modal('Create a workspace',`<form id="new-business-form">${field('name','Business name','','text','e.g. Cedar Auto Repair')}${field('industry','Industry','Local services')}<div class="field"><label>Timezone</label><select name="timezone"><option value="America/Chicago">Central · Chicago</option><option value="America/New_York">Eastern · New York</option><option value="America/Los_Angeles">Pacific · Los Angeles</option><option value="America/Denver">Mountain · Denver</option></select></div>${field('phone','Business phone (optional)','')}</form>`,`<button class="btn outline" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveBusiness()">Create workspace</button>`)}
async function saveBusiness(){await safe(async()=>{const f=formData('new-business-form');const r=await api('/businesses','POST',f);closeModal();S.me=await api('/auth/me');await switchBusiness(r.id);toast('Workspace created')})}
function openMember(){modal('Add a login member',`<form id="member-form">${field('name','Full name','','text','e.g. Sam Taylor')}${field('email','Email','','email','staff@example.com')}${field('password','Initial password','','password','At least 8 characters')}<div class="field"><label>Role</label><select name="role"><option value="staff">Staff · operational access</option><option value="owner">Owner · full business access</option></select></div><div class="info-note">This is a local demo: a member can sign in with the provided email and password. Invite emails and password resets are not implemented yet.</div></form>`,`<button class="btn outline" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveMember()">Add member</button>`)}
async function saveMember(){await safe(async()=>{await api('/members','POST',formData('member-form'));closeModal();await reload();toast('Member access created')})}
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
boot();
